00063 // Get directory part of current executable path - optionally add a filename
00064 //
00065 #if defined(_WIN32)
00066 std::string get_program() {
00067 
00068     // Get execuable name
00069     //
00070     char tmp[MAX_PATH];
00071     int s = GetModuleFileNameA(NULL, tmp, sizeof(tmp));
00072 
00073     return tmp;
00074 }
00075 
00076 std::string get_program_directory(const std::string &suffix) {
00077 
00078     // Get execuable name
00079     //
00080     char tmp[MAX_PATH];
00081     int s = GetModuleFileNameA(NULL, tmp, sizeof(tmp));
00082 
00083     // Trim away filename
00084     while (s > 0 && tmp[s - 1] != '\\' && tmp[s - 1] != '/' && tmp[s - 1] != ':')
00085         s--;
00086     tmp[s] = '\0';
00087 
00088     return tmp + suffix;
00089 }
00090 #else
00091 std::string get_program() {
00092     char tmp[PATH_MAX] = "";
00093 
00094     // Use /proc & readlink() to get real executable path
00095     char link[PATH_MAX];
00096     sprintf(link, "/proc/%d/exe", getpid());
00097     int s = readlink(link, tmp, sizeof(tmp));
00098 
00099     return tmp;
00100 }
00101 
00102 std::string get_program_directory(const std::string &suffix) {
00103     char tmp[PATH_MAX] = "";
00104 
00105     // Use /proc & readlink() to get real executable path
00106     char link[PATH_MAX];
00107     sprintf(link, "/proc/%d/exe", getpid());
00108     int s = readlink(link, tmp, sizeof(tmp));
00109 
00110     // Trim away filename
00111     while (s > 0 && tmp[s - 1] != '/')
00112         s--;
00113     tmp[s] = '\0';
00114 
00115     return tmp + suffix;
00116 }
00117 #endif
