00119 size_t file_size(int fd) {
00120     // VS2017 function stat
00121 #if defined _WIN32
00122     struct _stat64 stat_buf = {0};
00123     int ret = _fstat64(fd, &stat_buf);
00124     if (ret < 0)
00125         return -1;
00126 #else
00127     struct stat stat_buf = {0};
00128     if (fstat(fd, &stat_buf) < 0)
00129         return -1;
00130 #endif
00131 
00132     return stat_buf.st_size;
00133 }
00134 
00135 size_t file_size(const std::string &name) {
00136     // VS2017 function stat
00137 #if defined _WIN32
00138     struct _stat64 stat_buf = {0};
00139     int ret = _stat64(name.c_str(), &stat_buf);
00140     if (ret < 0)
00141         return -1;
00142 #else
00143     struct stat stat_buf = {0};
00144     if (stat(name.c_str(), &stat_buf) < 0)
00145         return -1;
00146 #endif
00147 
00148     return stat_buf.st_size;
00149 }
00150 
00151 std::string read_file(const std::string &name) {
00152     struct stat stat_buf = {0};
00153 
00154     if (stat(name.c_str(), &stat_buf) < 0)
00155         return "";
00156 
00157     UniquePtrFile f(fopen(name.c_str(), "rb"));
00158 
00159     if (!f)
00160         return "";
00161 
00162     std::vector<char> tmp(stat_buf.st_size + 1);
00163 
00164     if (fread(tmp.data(), 1, stat_buf.st_size, f.get()) != stat_buf.st_size)
00165         return "";
00166 
00167     tmp[stat_buf.st_size] = '\0';
00168     return std::string(tmp.begin(), tmp.end());
00169 }
00170 
00171 bool write_file(const std::string &name, const std::string &contents) {
00172     UniquePtrFile f(fopen(name.c_str(), "wb"));
00173     if (!f)
00174         return false;
00175 
00176     return fwrite(contents.data(), 1, contents.size(), f.get()) == contents.size();
00177 }
