00179 std::string lowercase(const char *s) {
00180     std::string r(s);
00181     std::transform(r.begin(), r.end(), r.begin(), ::tolower);
00182     return r;
00183 }
00184 
00185 std::string lowercase(const std::string &s) {
00186     std::string r(s);
00187     std::transform(r.begin(), r.end(), r.begin(), ::tolower);
00188     return r;
00189 }
00190 
00191 unsigned split(std::vector<std::string> &output, const std::string &src, const char *seperators) {
00192     bool in_token = false;
00193 
00194     std::string s;
00195 
00196     for (const auto c : src) {
00197         if (strchr(seperators, c)) {
00198             if (in_token) {
00199                 // End of token - push accumulated string to output
00200                 output.push_back(s);
00201                 in_token = false;
00202             } else {
00203                 // In seperators - do nothing
00204             }
00205         } else {
00206             if (in_token) {
00207                 // Still in token - accumulate
00208                 s.push_back(c);
00209             } else {
00210                 // Start of token - start new string
00211                 s.clear();
00212                 s.push_back(c);
00213                 in_token = true;
00214             }
00215         }
00216     }
00217 
00218     // Add any unfinished token
00219     if (!s.empty())
00220         output.push_back(s);
00221 
00222     return (unsigned)output.size();
00223 }
00224 
00225 // Return extension part of filename, or ""
00226 //
00227 #if defined _WIN32
00228 #define PATH_SEPERATORS "/\\:"
00229 #else
00230 #define PATH_SEPERATORS "/"
00231 #endif
00232 
00233 std::string file_extension(const std::string &filename) {
00234     size_t p = filename.find_last_of(PATH_SEPERATORS ".");
00235 
00236     if (p == std::string::npos || filename[p] != '.')
00237         return "";
00238 
00239     return filename.substr(p + 1);
00240 }
