00350 uint64_t crc64(uint64_t crc, const unsigned char *s, uint64_t l) {
00351     for (unsigned j = 0; j < l; j++)
00352         crc = crc64_tab[(uint8_t)crc ^ s[j]] ^ (crc >> 8);
00353 
00354     return crc;
00355 }
