00357 // Return a system-wide timstamp for debugging packet timing (in uSecs)
00358 //
00359 uint64_t system_timestamp() {
00360     static auto start = std::chrono::system_clock().now();
00361     auto d = std::chrono::system_clock().now() - start;
00362     return std::chrono::duration_cast<std::chrono::microseconds>(d).count();
00363 }
