00365 // Generate a temporary filename for storing
00366 std::string make_temporary_filename(const std::string &suffix) {
00367     char name[256];
00368     snprintf(name, sizeof(name), "_temp_%08d_%s", getpid(), suffix.c_str());
00369     return name;
00370 }
